/**
 * Unyfide — service worker.
 *
 * Hand-written rather than generated by `@serwist/next`, because what this app
 * needs is four routing rules over content that is already static. A build
 * plugin would add a dependency, a webpack/turbopack integration and a
 * generated precache manifest to express the same four rules, in a project
 * whose whole point is a thin dependency tree.
 *
 * The one thing a precache manifest buys — knowing this build's hashed asset
 * URLs up front — is recovered by `warm()` below: the page hands the worker
 * the exact URLs it just loaded, so the very first visit is enough to make the
 * next launch work offline.
 *
 * Strategies, and why each one:
 *
 *   /_next/static/*   cache-first. Content-addressed and immutable, so a hit
 *                     is always correct and a new build simply asks for new
 *                     URLs. This is what makes an offline launch instant.
 *   /icons/*          cache-first. Same reasoning, no hash but never changes.
 *   navigations, RSC  stale-while-revalidate. The question banks, decks and
 *                     cheat sheets are effectively static, and this is the
 *                     content that has to survive a commute with no signal.
 *                     Revalidating in the background is also what stops the
 *                     classic "stuck on an old build forever" bug — no HTML is
 *                     ever served cache-first.
 *   /api/feed/*       network-first with a cache fallback. Feed data is
 *                     time-sensitive and already carries a 3-hour HTTP cache;
 *                     serving it from the SW cache first would show stale news
 *                     to someone who is online. On failure the last response
 *                     is returned so the Feed degrades instead of breaking.
 *
 * Everything else is passed straight through: non-GET requests, cross-origin
 * requests (notably the two publisher image CDNs, which have their own
 * caching), and `/_next/image`, which proxies those same CDNs.
 *
 * Bump VERSION when the cache layout or a strategy changes. It does not need
 * bumping per deploy: nothing that can go stale is served cache-first.
 *
 * ---------------------------------------------------------------------------
 * PUSH lives at the bottom of this file and shares nothing with the caching
 * above — no cache, no strategy, no route. It is here because a service worker
 * is the only place a browser will run code for a page that is closed, which is
 * the entire point of a reminder. The three handlers are `push` (draw the
 * notification), `notificationclick` (open the right screen) and
 * `pushsubscriptionchange` (re-register when a push service rotates an
 * endpoint). None of them touches `classify`, the caches or the fetch handler.
 * ---------------------------------------------------------------------------
 */

const VERSION = 'v1'
const CACHE_PREFIX = 'aeg-'

const CACHES = {
  /** Precached non-HTML: the manifest and the icon set. */
  shell: `${CACHE_PREFIX}shell-${VERSION}`,
  /** Immutable build output. */
  static: `${CACHE_PREFIX}static-${VERSION}`,
  /** Documents and RSC payloads. */
  pages: `${CACHE_PREFIX}pages-${VERSION}`,
  /** The last successful feed response per endpoint. */
  feed: `${CACHE_PREFIX}feed-${VERSION}`,
}

const OFFLINE_URL = '/offline'
const START_URL = '/today'

/** Fetched at install so a cold offline launch has something to open. */
const PRECACHE_PAGES = [START_URL, OFFLINE_URL]
const PRECACHE_ASSETS = [
  '/manifest.webmanifest',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/icon-maskable-512.png',
  '/icons/apple-touch-icon.png',
]

/**
 * Paths whose responses are personal and must never enter a cache.
 *
 * Navigations are served stale-while-revalidate, which is exactly right for
 * question banks and exactly wrong for an account page: the cached copy would
 * be replayed from disk after sign-out, and to whoever opens this browser next.
 * There is no cross-user leak across the network here — the cache is per
 * profile — but "my data still on screen after I signed out" is the same bug
 * from where the user stands.
 *
 * The bare mini-app landing pages are deliberately absent: they are public
 * gates that hold no data, which is the same split `lib/auth/routes.ts`
 * enforces. `tests/unit/pwa.test.ts` asserts the two agree, because this file
 * cannot import that one — it is a classic script, evaluated in a worker.
 *
 * @param {string} path
 */
function isPrivatePath(path) {
  const p = path.length > 1 && path.endsWith('/') ? path.slice(0, -1) : path
  const under = (prefix) => p === prefix || p.startsWith(prefix + '/')
  if (under('/account') || under('/api/account')) return true
  if (under('/sign-in') || under('/sign-up') || under('/auth')) return true
  // Inside a mini-app, but not its landing page.
  for (const root of ['/diet', '/train', '/ops']) {
    if (p !== root && under(root)) return true
  }
  return false
}

/**
 * The routing table, as a pure function so it can be asserted directly.
 *
 * Takes a plain descriptor rather than a `Request` so the unit test does not
 * have to build one; the fetch handler below does the unwrapping.
 *
 * @param {{ method: string, mode: string, url: string, rsc: boolean }} req
 * @returns {{ strategy: string, cache: string } | null} null means "do not
 *   intercept" — the request goes to the network as if no worker existed.
 */
function classify(req) {
  if (req.method !== 'GET') return null

  let url
  try {
    url = new URL(req.url)
  } catch {
    return null
  }
  if (url.origin !== self.location.origin) return null

  const path = url.pathname

  // Before every other rule: nothing personal is ever stored.
  if (isPrivatePath(path)) return null

  if (path.startsWith('/api/feed/')) return { strategy: 'network-first', cache: CACHES.feed }
  // No other API route exists today; if one lands, it opts in deliberately.
  if (path.startsWith('/api/')) return null
  // Optimised publisher art. Same origin, but the bytes come from a CDN that
  // already caches them and they are large — not our cache's job.
  if (path.startsWith('/_next/image')) return null

  if (path.startsWith('/_next/static/')) return { strategy: 'cache-first', cache: CACHES.static }
  if (path.startsWith('/icons/')) return { strategy: 'cache-first', cache: CACHES.shell }

  if (req.mode === 'navigate') return { strategy: 'stale-while-revalidate', cache: CACHES.pages }
  if (req.rsc) return { strategy: 'stale-while-revalidate', cache: CACHES.pages }

  if (path === '/manifest.webmanifest' || path === '/favicon.ico') {
    return { strategy: 'stale-while-revalidate', cache: CACHES.shell }
  }

  return null
}

/**
 * The cache key for a request.
 *
 * A string, not the `Request`, on purpose: Next sends `Vary: RSC, ...` on
 * documents, and a stored `Request` would make cache matching depend on
 * header negotiation that differs between a prefetch and a reload. The RSC
 * payload URL already carries its own `_rsc` query param, so document and
 * payload never collide.
 */
function cacheKey(url) {
  return url.pathname + url.search
}

/** Only same-origin, complete, successful responses are worth storing. */
function isStorable(response) {
  return Boolean(response) && response.status === 200 && response.type === 'basic'
}

async function cacheFirst(request, key, cacheName) {
  const cache = await caches.open(cacheName)
  const hit = await cache.match(key)
  if (hit) return hit
  const response = await fetch(request)
  if (isStorable(response)) await cache.put(key, response.clone())
  return response
}

async function staleWhileRevalidate(event, request, key, cacheName) {
  const cache = await caches.open(cacheName)
  const hit = await cache.match(key)

  const revalidate = fetch(request).then(async (response) => {
    if (isStorable(response)) await cache.put(key, response.clone())
    return response
  })

  if (hit) {
    // Let the refresh finish after the cached copy has already been served.
    event.waitUntil(revalidate.catch(() => undefined))
    return hit
  }

  try {
    return await revalidate
  } catch (err) {
    if (request.mode === 'navigate') {
      const fallback = await caches.match(OFFLINE_URL)
      if (fallback) return fallback
    }
    throw err
  }
}

async function networkFirst(request, key, cacheName) {
  const cache = await caches.open(cacheName)
  try {
    const response = await fetch(request)
    if (isStorable(response)) await cache.put(key, response.clone())
    return response
  } catch (err) {
    const hit = await cache.match(key)
    if (hit) return hit
    // Nothing cached: fail exactly as the network would have, so the Feed's
    // own error state renders instead of a fabricated empty payload.
    throw err
  }
}

/**
 * Cache the build assets a page reports having loaded.
 *
 * Requests made before this worker activated were never seen by it, so a
 * first visit would otherwise leave the JS uncached and the next launch would
 * be HTML-only. The registrar posts `performance.getEntriesByType('resource')`
 * once it is in control; this stores the same-origin build output from it.
 */
async function warm(urls) {
  const cache = await caches.open(CACHES.static)
  await Promise.all(
    urls.slice(0, 200).map(async (raw) => {
      try {
        const url = new URL(raw, self.location.origin)
        if (url.origin !== self.location.origin) return
        if (!url.pathname.startsWith('/_next/static/')) return
        const key = cacheKey(url)
        if (await cache.match(key)) return
        const response = await fetch(url.href, { credentials: 'same-origin' })
        if (isStorable(response)) await cache.put(key, response)
      } catch {
        // A warm-up miss is not a failure; the asset caches on next use.
      }
    }),
  )
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      // Settled, not `addAll`: one 404 in the list would abort the whole
      // install and leave the app with no worker at all.
      const pages = await caches.open(CACHES.pages)
      const shell = await caches.open(CACHES.shell)
      await Promise.allSettled([
        ...PRECACHE_PAGES.map(async (path) => {
          const response = await fetch(path, { credentials: 'same-origin' })
          if (isStorable(response)) await pages.put(path, response)
        }),
        ...PRECACHE_ASSETS.map(async (path) => {
          const response = await fetch(path, { credentials: 'same-origin' })
          if (isStorable(response)) await shell.put(path, response)
        }),
      ])
      // Deliberate: the alternative is waiting for every tab to close, which is
      // exactly how PWAs strand people on an old build. It is safe here because
      // nothing HTML is served cache-first, so a mid-session swap cannot show
      // older content, and progress is written to localStorage synchronously,
      // so there is no in-flight state for a new worker to lose.
      await self.skipWaiting()
    })(),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set(Object.values(CACHES))
      const keys = await caches.keys()
      await Promise.all(
        keys
          .filter((key) => key.startsWith(CACHE_PREFIX) && !keep.has(key))
          .map((key) => caches.delete(key)),
      )
      // Paired with skipWaiting: take over the page that installed us, so the
      // first visit already populates the caches rather than the second.
      await self.clients.claim()
    })(),
  )
})

self.addEventListener('message', (event) => {
  const data = event.data
  if (!data || data.type !== 'aeg:warm' || !Array.isArray(data.urls)) return
  event.waitUntil(warm(data.urls))
})

self.addEventListener('fetch', (event) => {
  const request = event.request

  // DevTools issues these while the panel is open; responding to one throws.
  if (request.cache === 'only-if-cached' && request.mode !== 'same-origin') return

  const route = classify({
    method: request.method,
    mode: request.mode,
    url: request.url,
    rsc: request.headers.get('RSC') === '1',
  })
  if (!route) return

  const key = cacheKey(new URL(request.url))

  if (route.strategy === 'cache-first') {
    event.respondWith(cacheFirst(request, key, route.cache))
  } else if (route.strategy === 'network-first') {
    event.respondWith(networkFirst(request, key, route.cache))
  } else {
    event.respondWith(staleWhileRevalidate(event, request, key, route.cache))
  }
})

/* -------------------------------------------------------------------------- */
/* Push notifications                                                          */
/* -------------------------------------------------------------------------- */

/** Shown when the payload is missing or unreadable. See `notificationFrom`. */
const FALLBACK_NOTIFICATION = {
  title: 'Unyfide',
  body: 'You have a reminder.',
  url: '/ops/today',
  tag: 'unyfide-reminder',
}

const NOTIFICATION_ICON = '/icons/icon-192.png'
const SUBSCRIBE_URL = '/api/push/subscribe'

/**
 * The payload, parsed defensively, as a pure function so the unit test can
 * assert it without a browser.
 *
 * IT ALWAYS RETURNS SOMETHING. The subscription was created with
 * `userVisibleOnly: true`, which is a promise to the browser that every push
 * results in a visible notification; break it and Chrome shows its own "This
 * site has been updated in the background" notice instead, and repeated
 * offences can cost the site its push permission entirely. So a truncated body,
 * an empty push (some services send one to verify an endpoint) and a payload
 * from a future version of the sender all degrade to a real notification rather
 * than to nothing.
 *
 * `url` is validated rather than trusted. It is a same-origin PATH; anything
 * else — an absolute URL, a protocol-relative `//host`, a `javascript:` — falls
 * back. The payload is authored from the user's own task titles today, but a
 * notification handler that will open any URL it is handed is a redirect
 * primitive sitting in the one place that runs while the app is closed.
 *
 * @param {string | null | undefined} raw
 */
function notificationFrom(raw) {
  let data = null
  if (typeof raw === 'string' && raw !== '') {
    try {
      data = JSON.parse(raw)
    } catch {
      data = null
    }
  }
  if (!data || typeof data !== 'object') return { ...FALLBACK_NOTIFICATION }

  const text = (value, fallback) =>
    typeof value === 'string' && value.trim() !== '' ? value : fallback

  const url = typeof data.url === 'string' && /^\/(?!\/)/.test(data.url) ? data.url : FALLBACK_NOTIFICATION.url

  return {
    title: text(data.title, FALLBACK_NOTIFICATION.title),
    body: text(data.body, ''),
    url,
    tag: text(data.tag, FALLBACK_NOTIFICATION.tag),
  }
}

self.addEventListener('push', (event) => {
  const payload = notificationFrom(event.data ? event.data.text() : null)

  event.waitUntil(
    self.registration.showNotification(payload.title, {
      body: payload.body,
      icon: NOTIFICATION_ICON,
      badge: NOTIFICATION_ICON,
      // The tag is the delivery key, so a redelivery of the same reminder
      // replaces the one already on screen instead of stacking beside it. This
      // is the second line of defence; `push_delivery` is the first.
      tag: payload.tag,
      // Do not re-alert for a replacement: the point of the tag is that this is
      // the same reminder, and buzzing twice for it is the bug it prevents.
      renotify: false,
      // Carried through to `notificationclick`, which is a separate event with
      // no access to this scope's variables.
      data: { url: payload.url },
    }),
  )
})

/**
 * Open what the notification was about.
 *
 * Focus-then-navigate rather than always opening a window: a reminder tapped
 * while the app is already open in a tab should bring that tab forward, not
 * strand the user with two copies of the app. `openWindow` is the fallback for
 * the case the whole point of push exists to serve — nothing is running.
 *
 * Both branches are inside `waitUntil`, because the worker may have been woken
 * only to deliver this notification and would otherwise be free to die
 * mid-navigation.
 */
self.addEventListener('notificationclick', (event) => {
  event.notification.close()

  const target = new URL(
    (event.notification.data && event.notification.data.url) || FALLBACK_NOTIFICATION.url,
    self.location.origin,
  ).href

  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })

      // Already showing the right screen: bring it forward and stop.
      for (const client of windows) {
        if (client.url === target) {
          await client.focus().catch(() => undefined)
          return
        }
      }

      // NAVIGATE BEFORE FOCUS, and never let a failed focus cancel the
      // navigation. `WindowClient#focus()` rejects without user activation —
      // which a real notification click has and a programmatic dispatch does
      // not — and doing it first meant the rejection threw away the navigate()
      // that was the whole point. The user ends up on the right page either
      // way; whether the window also comes forward is the part the browser may
      // refuse.
      const existing = windows[0]
      if (existing && 'navigate' in existing) {
        const navigated = await existing.navigate(target).catch(() => null)
        if (navigated) {
          await navigated.focus().catch(() => undefined)
          return
        }
      }

      return self.clients.openWindow(target)
    })(),
  )
})

/**
 * A push service may retire a subscription and issue a new one — Chrome does it
 * when its own registration rotates, Firefox on some upgrades. The old endpoint
 * then answers 410 forever and the device silently stops receiving anything.
 *
 * This is the only notice we get. Re-subscribe with the same application server
 * key and tell the server, so the row is replaced rather than left to be
 * garbage-collected on a 410 with nothing to take its place.
 *
 * `event.oldSubscription` carries the key on the browsers that fire this, which
 * is why the new subscription can be created without the page's help — there
 * may not be a page.
 */
self.addEventListener('pushsubscriptionchange', (event) => {
  event.waitUntil(
    (async () => {
      try {
        const previous = event.oldSubscription
        const applicationServerKey = previous && previous.options && previous.options.applicationServerKey
        if (!applicationServerKey) return

        const subscription =
          event.newSubscription ??
          (await self.registration.pushManager.subscribe({
            userVisibleOnly: true,
            applicationServerKey,
          }))

        const json = subscription.toJSON()
        await fetch(SUBSCRIBE_URL, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          // The session cookie is what identifies the account; without it the
          // route answers 401 and the device stays unreachable.
          credentials: 'same-origin',
          body: JSON.stringify({
            endpoint: subscription.endpoint,
            keys: { p256dh: json.keys && json.keys.p256dh, auth: json.keys && json.keys.auth },
            timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC',
          }),
        })
      } catch {
        // Nothing useful to do from here. The next time the user opens the app,
        // the Reminders screen sees no subscription and offers to turn it back
        // on, which is the recovery path a person can actually act on.
      }
    })(),
  )
})

// Exposed only when this file is evaluated as a module by the unit test;
// `module` is undefined in a worker, so this is a no-op in the browser.
if (typeof module !== 'undefined' && module) {
  module.exports = { classify, cacheKey, isPrivatePath, notificationFrom, CACHES, CACHE_PREFIX, VERSION, OFFLINE_URL, START_URL, PRECACHE_PAGES, PRECACHE_ASSETS, FALLBACK_NOTIFICATION }
}
